// hw-testing-rack — interactive 3D viewer.
// Scene data comes from assets/rack.json (generated by tools/build.py web),
// printed-part meshes from assets/parts.glb, PCBs from assets/pcb/*.glb when present.
// Everything is authored in millimetres with Z up; `root` turns it into three.js' Y-up.
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { toCreasedNormals } from 'three/addons/utils/BufferGeometryUtils.js';

const $ = (id) => document.getElementById(id);
const params = new URLSearchParams(location.search);

// ------------------------------------------------------------------ renderer / scene
const container = $('viewport');
const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: params.has('capture') });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
container.appendChild(renderer.domElement);

const labelRenderer = new CSS2DRenderer();
labelRenderer.setSize(window.innerWidth, window.innerHeight);
Object.assign(labelRenderer.domElement.style, { position: 'fixed', inset: '0', pointerEvents: 'none' });
container.appendChild(labelRenderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0e1116);
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 5, 20000);
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI * 0.53;
controls.minDistance = 40;            // close enough to see the 0.2 mm layers
controls.zoomToCursor = true;
controls.maxDistance = 5000;

const sun = new THREE.DirectionalLight(0xffffff, 2.2);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.6;
scene.add(sun, sun.target);
scene.add(new THREE.HemisphereLight(0xdfe8ff, 0x1a1d22, 0.55));

const root = new THREE.Group();          // Z-up, millimetres
root.rotation.x = -Math.PI / 2;
scene.add(root);

// ------------------------------------------------------------------ materials
const std = (color, metalness = 0, roughness = 0.55, extra = {}) =>
  new THREE.MeshStandardMaterial({ color, metalness, roughness, ...extra });
const MAT = {
  ladders: std(0x2a2e35, 0, 0.62),
  trays: std(0x3b414b, 0, 0.58),
  braces: std(0xff8a3d, 0, 0.42),
  framePlates: std(0x31363f, 0, 0.6),
  drawers: std(0xe3e6ea, 0, 0.48),
  plates: std(0x2f6fde, 0, 0.45),
  chain: std(0x15171b, 0.1, 0.5),
  chainParts: std(0xff8a3d, 0, 0.45),
  cameras: std(0x2a2e35, 0, 0.55),
  psu: std(0xb9bdc3, 0.85, 0.32),
  powerBox: std(0x4b525d, 0, 0.55),
  pcb: std(0x10151c, 0.1, 0.42),
  pcbGreen: std(0x0f3d23, 0.1, 0.42),
  silver: std(0xc9ccd1, 0.9, 0.28),
  blackPlastic: std(0x18191c, 0, 0.6),
  whitePlastic: std(0xeceae4, 0, 0.6),
  gold: std(0xd4a64a, 0.9, 0.3),
  inductor: std(0x2b2b2b, 0.2, 0.55),
};
const CABLE_COLORS = {
  'c-to-c': 0x8f5cff, 'c-to-micro-b': 0xffb02e, 'c-to-mini-b': 0xe08a1e,
  power: 0xff5a5a, pc: 0x3fb6ff, ext: 0x7d8590, 'usb-pd': 0x101114,
};

// Layer lines on the printed parts.  Each part mesh carries `printUp`, its build plate's normal
// (rack.json › print.up), so the lines run the way the part is printed (ladders and braces lie
// flat: their lines go round the edges).  Every layer is a rounded bead: the normal tilts down at
// its bottom and up at its top, with a dark seam between beads.  Both are averaged over the
// pixel's footprint, so the lines fade out instead of flickering once a layer is under a pixel.
const LAYER = { h: 0.2 };
function printLook(mat) {
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.layerH = { value: LAYER.h };
    sh.vertexShader = sh.vertexShader
      .replace('void main() {', 'attribute vec3 printUp;\nuniform float layerH;\nvarying float vLayer;\nvarying vec3 vUpView;\nvoid main() {')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvLayer = dot(position, printUp) / layerH;\nvUpView = normalMatrix * printUp;');
    sh.fragmentShader = sh.fragmentShader
      .replace('void main() {', `varying float vLayer;
varying vec3 vUpView;
// box-filtered over [a, b] (in layers): the bead's slope 2t-1 and its seam (2t-1)^2, t = fract
float beadSlope(float a, float b) { float fa = fract(a), fb = fract(b); return ((fb * fb - fb) - (fa * fa - fa)) / (b - a); }
float seamG(float x) { float s = 2.0 * fract(x) - 1.0; return floor(x) / 3.0 + (s * s * s + 1.0) / 6.0; }
void main() {`)
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
if (dot(vUpView, vUpView) > 0.01) {
  vec3 up = normalize(vUpView);
  float w = max(fwidth(vLayer), 1e-3);
  float a = vLayer - 0.5 * w, b = vLayer + 0.5 * w;
  float on = smoothstep(0.15, 0.6, 1.0 - abs(dot(normal, up))) * (1.0 - smoothstep(0.45, 0.9, w));
  normal = normalize(normal + up * beadSlope(a, b) * 0.8 * on);
  diffuseColor.rgb *= 1.0 - 0.5 * on * ((seamG(b) - seamG(a)) / w - 1.0 / 3.0);
}`);
  };
  return mat;
}
for (const k of ['ladders', 'trays', 'braces', 'framePlates', 'drawers', 'plates', 'chainParts', 'cameras', 'powerBox']) printLook(MAT[k]);

function partMaterial(name) {
  if (name.startsWith('ladder_')) return MAT.ladders;
  if (name.startsWith('brace_')) return MAT.braces;
  if (name === 'tray') return MAT.trays;
  if (name === 'floor_plate' || name === 'cap_plate') return MAT.framePlates;
  if (name === 'drawer') return MAT.drawers;
  if (name.startsWith('chain_')) return MAT.chainParts;
  if (name.startsWith('plate_')) return MAT.plates;
  if (name.startsWith('camera_')) return MAT.cameras;
  if (name.startsWith('power_box_')) return MAT.powerBox;
  return MAT.trays;
}

// ------------------------------------------------------------------ layers
const LAYERS = [
  ['ladders', 'Ladders', true], ['braces', 'Rear braces', true], ['frameplates', 'Floor & cap plates', true],
  ['trays', 'Trays', true], ['drawers', 'Drawers', true], ['plates', 'Board plates', true], ['boards', 'Dev boards', true],
  ['nodes', 'Bay nodes', true], ['chain', 'Drag chains', true], ['cables', 'USB cables', true], ['power', 'Row cables', true],
  ['cameras', 'Cameras', true], ['labels', 'Bay labels', true],
  ['powerbox', 'Power box', true], ['powerlid', 'Power box lid', true],
];
const layerOn = Object.fromEntries(LAYERS.map(([k, , on]) => [k, on]));
const rowGroups = [];             // one group per (tilted) row, the cap level included

// Every placed object is tracked so layers / drawers / explode can act on it.
// space "row": coordinates in that row's frame (child of rowGroups[row]); "frame": child of root.
const tracked = [];
function track(obj, { layer, bay = null, row = null, movable = false, zone = 'trays', space = 'frame' }) {
  obj.userData = { ...obj.userData, layer, bay, row, movable, zone, space, base: obj.position.clone() };
  obj.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; o.userData.bay = bay; } });
  (space === 'row' && row != null ? rowGroups[row] : root).add(obj);
  tracked.push(obj);
  return obj;
}

// ------------------------------------------------------------------ helpers
const deg = THREE.MathUtils.degToRad;
const v3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);

function rowIndexOfBay(bay) {
  if (!bay) return null;
  return DATA.rack.rows.findIndex((r) => r.id === bay[0]);
}

function box(w, l, h, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, l, h), mat);
  m.position.set(x + w / 2, y + l / 2, z + h / 2);
  return m;
}

function textTexture(text, { bg = '#ffffff', fg = '#111111', w = 256, h = 64, font = 'bold 34px Inter, Arial' } = {}) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');
  g.fillStyle = bg; g.fillRect(0, 0, w, h);
  g.fillStyle = fg; g.font = font; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(text, w / 2, h / 2 + 2);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

function seeded(str) {
  let h = 2166136261;
  for (const ch of str) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  return () => ((h = Math.imul(h ^ (h >>> 15), 2246822507) ^ Math.imul(h ^ (h >>> 13), 3266489909)) >>> 0) / 4294967296;
}

// ------------------------------------------------------------------ dev boards
const USB_DIM = { 'usb-c': [9.0, 7.4, 3.2], 'micro-b': [7.6, 5.4, 2.7], 'mini-b': [7.8, 9.0, 4.0] };

function makeBoard(b) {
  const g = new THREE.Group();
  const [w, l] = b.size;
  const pcbMat = std(new THREE.Color(b.color), 0.05, 0.5);
  g.add(box(w, l, 1.6, pcbMat));
  const rnd = seeded(b.id + b.bay);
  const dark = new THREE.Color(b.color).getHSL({}).l > 0.5 ? MAT.blackPlastic : MAT.blackPlastic;
  // a few ICs and passives, and header rows along the long edges
  const n = Math.max(3, Math.round((w * l) / 1400));
  for (let i = 0; i < n; i++) {
    const cw = 4 + rnd() * Math.min(14, w * 0.3), cl = 4 + rnd() * Math.min(14, l * 0.25);
    const cx = 3 + rnd() * Math.max(1, w - cw - 6), cy = 3 + rnd() * Math.max(1, l - cl - 14);
    g.add(box(cw, cl, 1.0 + rnd() * 1.4, i % 3 ? dark : MAT.silver, cx, cy, 1.6));
  }
  if (w > 24 && l > 40) {
    for (const x of [1.2, w - 3.7]) g.add(box(2.5, l * 0.62, 8.5, MAT.blackPlastic, x, l * 0.18, 1.6));
  }
  // debug USB on the rear edge (+Y) — or the right edge (+X) for boards turned sideways
  for (const [ux, type] of [[b.usb_x, b.usb_type], [b.usb2_x, 'usb-c']]) {
    if (ux == null) continue;
    const d = USB_DIM[type] || USB_DIM['usb-c'];
    if (b.usb_side) g.add(box(d[1], d[0], d[2], MAT.silver, w - d[1] + 0.8, ux - d[0] / 2, 1.6));
    else g.add(box(d[0], d[1], d[2], MAT.silver, ux - d[0] / 2, l - d[1] + 0.8, 1.6));
  }
  // silkscreen-style label
  const tex = textTexture(b.label || b.id, { bg: 'rgba(0,0,0,0)', fg: '#ffffff', w: 512, h: 96, font: 'bold 54px Inter, Arial' });
  const lbl = new THREE.Mesh(new THREE.PlaneGeometry(Math.min(w * 0.85, 60), Math.min(w * 0.85, 60) * 96 / 512),
    new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false }));
  lbl.position.set(w / 2, Math.min(10, l * 0.2), 1.62);
  g.add(lbl);
  g.position.set(...b.pos);
  return g;
}

// ------------------------------------------------------------------ PCB stand-ins
// Coordinates are KiCad (x right, y towards the FRONT edge); `pos` is the KiCad origin
// (rear-left corner) in rack coordinates, so rack = pos + (x, -y, z).
function kbox(g, kx, ky, w, l, h, mat, z = 1.6) { g.add(box(w, l, h, mat, kx - w / 2, -ky - l / 2, z)); }

function makeNodeStandIn() {
  const g = new THREE.Group();
  g.add(box(64, 80, 1.6, MAT.pcb, 0, -80, 0));
  kbox(g, 30, 11.5, 15.4, 20.5, 2.4, MAT.silver);                 // ESP32-S3-MINI-1
  kbox(g, 32, 76.5, 8.9, 7.4, 3.2, MAT.silver);                   // PC port
  kbox(g, 60.5, 20, 7.4, 8.9, 3.2, MAT.silver);                   // DUT port
  kbox(g, 60.5, 32, 7.4, 8.9, 3.2, MAT.silver);                   // PWR port
  kbox(g, 15.7, 34, 7, 6.6, 3, MAT.inductor);                     // buck inductor (FXL0630)
  kbox(g, 3, 63, 7.6, 6, 4.8, MAT.whitePlastic);                  // row cable in (JST PH 6)
  kbox(g, 61, 63, 7.6, 6, 4.8, MAT.whitePlastic);                 // row cable out (JST PH 6)
  kbox(g, 59, 45, 4.5, 6, 3, MAT.whitePlastic);                   // AUX SH
  kbox(g, 50, 3, 6, 4.5, 6, MAT.whitePlastic);                    // CAM PH
  kbox(g, 12, 78.5, 2, 2, 0.9, MAT.whitePlastic);                 // LED
  kbox(g, 6, 49, 8, 8, 10.2, MAT.silver);                         // bulk cap
  return g;
}

function makeHubStandIn() {
  // hub v0.4 (76 × 140, KiCad y = 0 at the rear), used until its GLB exists: row outputs on the left
  // edge, LEDs and USB-C at the front, the rack controller's ESP32-S3 module at the rear
  const g = new THREE.Group();
  g.add(box(76, 140, 1.6, MAT.pcb, 0, -140, 0));
  for (const y of [115, 92, 69, 46]) {
    kbox(g, 2.4, y, 7.6, 15.9, 5.5, MAT.whitePlastic);             // row outputs (6-pin JST PH, side entry)
    kbox(g, 26, y - 0.5, 4.4, 5, 1.2, MAT.blackPlastic);           // eFuse
  }
  kbox(g, 69.2, 116, 13.9, 9, 10, MAT.whitePlastic);               // 24 V input (JST VH, side entry)
  kbox(g, 68.5, 86, 10, 10, 10.5, MAT.silver);                    // bulk caps
  kbox(g, 68.5, 74, 10, 10, 10.5, MAT.silver);
  kbox(g, 30, 10.5, 15.4, 20.5, 2.4, MAT.silver);                  // ESP32-S3-MINI-1
  kbox(g, 70, 136.6, 8.9, 7.4, 3.2, MAT.silver);                   // USB-C
  return g;
}

// ------------------------------------------------------------------ drag chain
function chainPath(ch, frac) {
  const t = ch.travel * frac;
  const [fx, fy] = ch.fixed;
  const mx = ch.moving_x, my = ch.moving_y - t, b = ch.bend_y - t / 2, r = ch.radius;
  const cx = (fx + mx) / 2;
  const pts = [];
  const push = (x, y) => pts.push(new THREE.Vector3(ch.origin[0] + x, ch.origin[1] + y, ch.origin[2] + ch.z));
  for (let y = fy; y < b; y += 3) push(fx, y);
  for (let k = 0; k <= 24; k++) { const a = Math.PI - (Math.PI * k) / 24; push(cx + r * Math.cos(a), b + r * Math.sin(a)); }
  for (let y = b - 3; y > my; y -= 3) push(mx, y);
  push(mx, my);
  return pts;
}

const linkGeoms = {};      // one box per chain size: along X; plan width Y; height Z
function linkGeom(ch) {
  const k = `${ch.pitch}x${ch.height}x${ch.width}`;
  return linkGeoms[k] ??= new THREE.BoxGeometry(ch.pitch * 0.94, ch.height, ch.width);
}
function layoutChain(inst, ch, frac) {
  const pts = chainPath(ch, frac);
  const seg = [];
  let total = 0;
  for (let i = 1; i < pts.length; i++) { const d = pts[i].distanceTo(pts[i - 1]); seg.push(d); total += d; }
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(1, 1, 1);
  let idx = 0, acc = 0, k = 0;
  for (let dist = ch.pitch / 2; dist < total && k < inst.count; dist += ch.pitch, k++) {
    while (idx < seg.length - 1 && acc + seg[idx] < dist) { acc += seg[idx]; idx++; }
    const f = (dist - acc) / seg[idx];
    const p = pts[idx].clone().lerp(pts[idx + 1], f);
    const dir = pts[idx + 1].clone().sub(pts[idx]).normalize();
    q.setFromUnitVectors(new THREE.Vector3(1, 0, 0), dir);
    m.compose(p, q, s);
    inst.setMatrixAt(k, m);
  }
  for (; k < inst.count; k++) { m.makeScale(0, 0, 0); inst.setMatrixAt(k, m); }
  inst.instanceMatrix.needsUpdate = true;
}

// ------------------------------------------------------------------ cables
function cableColor(c) {
  if (c.color) return new THREE.Color(c.color);
  if (c.kind === 'dut') return new THREE.Color(CABLE_COLORS[c.type] ?? 0x8f5cff);
  return new THREE.Color(CABLE_COLORS[c.kind] ?? 0x888888);
}
// USB plugs, modelled from the connectors' real outlines (mm).  Plug frame: +z = into the
// receptacle (the shell, mostly hidden in it), x = connector width, y = its "up".
const PLUG = {
  'usb-c':   { shell: 'pill', sw: 8.3, sh: 2.5, sl: 6.5, mw: 12.0, mh: 6.2, ml: 15, relief: 7 },
  'micro-b': { shell: 'trap', sw: 6.9, sh: 1.85, sl: 5.5, bw: 5.4, mw: 10.5, mh: 5.4, ml: 13, relief: 6 },
  'mini-b':  { shell: 'trap', sw: 7.7, sh: 3.9, sl: 6.0, bw: 6.2, mw: 11.0, mh: 7.0, ml: 14, relief: 6 },
  'usb-a':   { shell: 'box', sw: 12.0, sh: 4.5, sl: 12.0, mw: 15.5, mh: 7.5, ml: 20, relief: 8 },
};
const RIGHT_ANGLE = { depth: 12, height: 9, relief: 6 };   // must match tools/webscene.py
const PLUG_MAT = {
  mold: std(0x1d1f23, 0, 0.5),
  shell: std(0xd4d7dc, 0.95, 0.28),
  tongue: std(0x0b0c0e, 0, 0.6),
  screw: std(0xb9bdc4, 0.9, 0.35),
};
const plugGeoCache = new Map();
function cached(key, make) {
  if (!plugGeoCache.has(key)) plugGeoCache.set(key, make());
  return plugGeoCache.get(key);
}
function shellGeometry(d) {
  return cached(`shell-${d.shell}-${d.sw}-${d.sh}-${d.sl}`, () => {
    const s = new THREE.Shape();
    const w = d.sw / 2, h = d.sh / 2;
    if (d.shell === 'pill') {                    // USB-C: a stadium
      s.moveTo(-w + h, -h); s.lineTo(w - h, -h); s.absarc(w - h, 0, h, -Math.PI / 2, Math.PI / 2);
      s.lineTo(-w + h, h); s.absarc(-w + h, 0, h, Math.PI / 2, 3 * Math.PI / 2);
    } else if (d.shell === 'trap') {             // micro-B / mini-B: a trapezoid, wide side up
      const b = d.bw / 2;
      s.moveTo(-b, -h); s.lineTo(b, -h); s.lineTo(w, h * 0.2); s.lineTo(w, h); s.lineTo(-w, h); s.lineTo(-w, h * 0.2);
    } else {
      s.moveTo(-w, -h); s.lineTo(w, -h); s.lineTo(w, h); s.lineTo(-w, h);
    }
    s.closePath();
    return new THREE.ExtrudeGeometry(s, { depth: d.sl, bevelEnabled: false, curveSegments: 10 });
  });
}
function plugBasis(e) {
  const z = v3(e.dir).normalize();
  const up = v3(e.up ?? [0, 0, 1]);
  const x = new THREE.Vector3().crossVectors(up, z);
  if (x.lengthSq() < 1e-6) x.set(1, 0, 0);
  x.normalize();
  const y = new THREE.Vector3().crossVectors(z, x);
  return new THREE.Matrix4().makeBasis(x, y, z).setPosition(v3(e.at));
}
function makePlug(e) {
  const d = PLUG[e.type] ?? PLUG['usb-c'];
  const g = new THREE.Group();
  g.matrixAutoUpdate = false;
  g.matrix.copy(plugBasis(e));
  g.add(new THREE.Mesh(shellGeometry(d), PLUG_MAT.shell));
  if (e.style === 'right') {
    const { depth, height, relief } = RIGHT_ANGLE;
    const lo = -d.mh / 2 - 0.4;
    const mold = new THREE.Mesh(cached(`rmold-${d.mw}-${depth}-${height}-${lo}`,
      () => new RoundedBoxGeometry(d.mw, height - lo, depth, 3, 1.8)), PLUG_MAT.mold);
    mold.position.set(0, (height + lo) / 2, -depth / 2);
    const rel = new THREE.Mesh(cached('rrelief', () => new THREE.CylinderGeometry(2.2, 2.7, relief, 20)), PLUG_MAT.mold);
    rel.position.set(0, height + relief / 2, -depth / 2);
    g.add(mold, rel);
  } else {
    const mold = new THREE.Mesh(cached(`mold-${d.mw}-${d.mh}-${d.ml}`,
      () => new RoundedBoxGeometry(d.mw, d.mh, d.ml, 3, Math.min(2.2, d.mh / 2 - 0.2))), PLUG_MAT.mold);
    mold.position.set(0, 0, -d.ml / 2);
    const rel = new THREE.Mesh(cached('relief', () => new THREE.CylinderGeometry(2.7, 2.2, d.relief, 20)), PLUG_MAT.mold);
    rel.rotation.x = Math.PI / 2;
    rel.position.set(0, 0, -d.ml - d.relief / 2);
    g.add(mold, rel);
  }
  if (e.socket === 'panel') {
    // panel-mount female USB-C (the drawer's DATA port): flange with two M3 screws on the wall face
    const flange = new THREE.Mesh(cached('flange', () => new RoundedBoxGeometry(23, 8, 1.5, 2, 0.6)), PLUG_MAT.mold);
    flange.position.set(0, 0, 0.75);
    g.add(flange);
    for (const sx of [-9, 9]) {
      const scr = new THREE.Mesh(cached('screw', () => new THREE.CylinderGeometry(2.6, 2.6, 1.1, 16)), PLUG_MAT.screw);
      scr.rotation.x = Math.PI / 2;
      scr.position.set(sx, 0, -0.5);
      g.add(scr);
    }
  }
  return g;
}

function makeCable(c) {
  const g = new THREE.Group();
  const pts = c.points.map(v3);
  const curve = new THREE.CatmullRomCurve3(pts, false, 'centripetal');
  const jacket = std(cableColor(c), 0, c.kind.startsWith('power') || c.kind === 'usb-pd' ? 0.6 : 0.45,
    { envMapIntensity: 0.6 });
  const len = curve.getLength();
  g.add(new THREE.Mesh(new THREE.TubeGeometry(curve, Math.max(48, Math.round(len / 2)), c.radius || 1.5, 14, false), jacket));
  for (const e of c.ends ?? []) g.add(makePlug(e));
  return g;
}

function makeLaptop(p) {
  // a plain laptop, so the "classic mode" cable has somewhere to go
  const g = new THREE.Group();
  const [w, d, t] = p.size;
  const alu = std(0x8a8f96, 0.85, 0.32);
  const base = new THREE.Mesh(new RoundedBoxGeometry(w, d, t, 3, 3), alu);
  base.position.z = t / 2;
  const keys = new THREE.Mesh(new THREE.BoxGeometry(w - 40, d * 0.42, 0.6), std(0x202226, 0, 0.7));
  keys.position.set(0, d * 0.12, t + 0.2);
  const pad = new THREE.Mesh(new THREE.BoxGeometry(110, 65, 0.4), std(0x9aa0a8, 0.6, 0.3));
  pad.position.set(0, -d * 0.27, t + 0.1);
  const hinge = new THREE.Group();
  hinge.position.set(0, d / 2 - 2, t);
  hinge.rotation.x = -THREE.MathUtils.degToRad((p.lid_deg ?? 110) - 90);
  const lid = new THREE.Mesh(new RoundedBoxGeometry(w, 5, d - 6, 3, 2.5), alu);
  lid.position.set(0, 2.5, (d - 6) / 2);
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 640;
  const x = c.getContext('2d');
  x.fillStyle = '#16181f'; x.fillRect(0, 0, 1024, 640);
  x.font = '26px Consolas, Menlo, monospace';
  const lines = [['#82d678', 'dev@bench:~$ ', '#d6dae4', 'tio /dev/ttyACM0'], ['#66d6de', '*** Booting Zephyr OS ***', '', ''],
    ['#82d678', 'uart:~$ ', '#d6dae4', 'kernel version'], ['#d6dae4', 'Zephyr version 4.2.0', '', ''],
    ['#82d678', 'uart:~$ ', '#d6dae4', 'device list'], ['#d6dae4', '- gpio@40020000 (READY)', '', ''],
    ['#82d678', 'uart:~$ ', '#d6dae4', '█']];
  lines.forEach(([c1, t1, c2, t2], i) => {
    x.fillStyle = c1; x.fillText(t1, 40, 70 + i * 44);
    x.fillStyle = c2; x.fillText(t2, 40 + x.measureText(t1).width, 70 + i * 44);
  });
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const screen = new THREE.Mesh(new THREE.PlaneGeometry(w - 24, d - 30),
    new THREE.MeshStandardMaterial({ color: 0x000000, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: 0.9, roughness: 0.15 }));
  screen.rotation.x = Math.PI / 2;
  screen.position.set(0, -0.2, (d - 6) / 2);
  hinge.add(lid, screen);
  g.add(base, keys, pad, hinge);
  g.position.set(...p.pos);
  return g;
}

// ------------------------------------------------------------------ build
let DATA, GEOMS = {};
const drawerFrac = {};          // bay id → 0..1
const drawerTarget = {};
const initialOpen = {};         // drawer state baked into rack.json positions
const chainInstances = [];      // {inst, ch}
let selectedBay = null;
const selectionBox = new THREE.Box3Helper(new THREE.Box3(), 0xff8a3d);
selectionBox.visible = false;
root.add(selectionBox);

async function load() {
  const [json, gltf] = await Promise.all([
    fetch('assets/rack.json').then((r) => r.json()),
    new GLTFLoader().loadAsync('assets/parts.glb'),
  ]);
  DATA = json;
  LAYER.h = DATA.print?.layer ?? LAYER.h;
  gltf.scene.updateMatrixWorld(true);
  gltf.scene.traverse((o) => {
    if (o.isMesh) {
      const name = (o.parent && o.parent !== gltf.scene && !o.name) ? o.parent.name : o.name;
      // sharp edges stay sharp (flat faces, crisp corners), only curved walls are smoothed
      const geo = toCreasedNormals(o.geometry.clone().applyMatrix4(o.matrixWorld), deg(35));
      const up = DATA.print?.up?.[name] ?? [0, 0, 1];
      geo.setAttribute('printUp', new THREE.Float32BufferAttribute(
        new Float32Array(geo.attributes.position.count * 3).map((_, i) => up[i % 3]), 3));
      GEOMS[name] = geo;
    }
  });
  // PCB GLBs exported from KiCad (optional)
  const pcbGlb = {};
  for (const name of ['bay-node', 'power-hub']) {
    try {
      const g = await new GLTFLoader().loadAsync(`assets/pcb/${name}.glb`);
      pcbGlb[name] = g.scene;
    } catch { /* stand-in */ }
  }
  build(pcbGlb);
}

function build(pcbGlb) {
  const R = DATA.rack;
  for (const r of R.rows) {
    const g = new THREE.Group();
    g.position.set(...r.origin);
    g.rotation.x = deg(r.tilt);
    g.userData.origin = g.position.clone();
    root.add(g);
    rowGroups.push(g);
  }
  // printed parts
  for (const it of DATA.instances) {
    const geo = GEOMS[it.part];
    if (!geo) { console.warn('missing mesh', it.part); continue; }
    const m = new THREE.Mesh(geo, partMaterial(it.part));
    m.position.set(...it.pos);
    m.rotation.set(deg(it.rot[0]), deg(it.rot[1]), deg(it.rot[2]));
    track(m, { layer: it.layer, bay: it.bay, row: it.row, movable: !!it.movable, zone: it.layer, space: it.space });
  }
  // dev boards
  for (const b of DATA.boards) track(makeBoard(b), { layer: 'boards', bay: b.bay, row: b.row, movable: true, zone: 'boards', space: 'row' });
  // PCBs
  for (const p of DATA.pcbs) {
    const src = pcbGlb[p.board];
    const g = src ? src.clone(true) : (p.board === 'bay-node' ? makeNodeStandIn() : makeHubStandIn());
    g.position.set(...p.pos);
    track(g, { layer: p.board === 'bay-node' ? 'nodes' : 'power', bay: p.bay || null, row: p.row ?? null, zone: 'pcb', space: p.space });
  }
  // boxes (PSU, cameras)
  for (const bx of DATA.boxes) {
    const g = new THREE.Group();
    const mat = bx.kind === 'psu' ? MAT.psu : std(new THREE.Color(bx.color), 0.1, 0.5);
    g.add(box(bx.size[0], bx.size[1], bx.size[2], mat));
    if (bx.label) {           // a box's label, along its length
      const lbl = new THREE.Mesh(new THREE.PlaneGeometry(bx.size[1] * 0.7, bx.size[0] * 0.28), new THREE.MeshBasicMaterial({ map: textTexture(bx.label, { bg: '#2c5fa8', fg: '#fff', w: 512, h: 96, font: 'bold 44px Arial' }) }));
      lbl.rotation.z = Math.PI / 2;
      lbl.position.set(bx.size[0] / 2, bx.size[1] / 2, bx.size[2] + 0.05);
      g.add(lbl);
    }
    if (bx.kind === 'xiao') g.add(box(8, 8, 3, MAT.blackPlastic, bx.size[0] / 2 - 4, bx.size[1] / 2 - 4, -3));
    g.position.set(...bx.pos);
    track(g, { layer: bx.layer, bay: bx.bay || null, row: bx.row ?? null, zone: bx.layer, space: bx.space });
  }
  // status LEDs in the fascia windows (glow; colour = mode)
  for (const l of DATA.leds || []) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.5, 1.2, 16),
      new THREE.MeshStandardMaterial({ color: l.color, emissive: l.color, emissiveIntensity: 2.2 }));
    m.position.set(l.pos[0], l.pos[1] + 0.6, l.pos[2]);
    track(m, { layer: l.layer ?? 'nodes', bay: l.bay ?? null, row: l.row ?? null, zone: 'led', space: l.space ?? 'row' });
  }
  // chains
  for (const ch of DATA.chains) {
    const inst = new THREE.InstancedMesh(linkGeom(ch), MAT.chain, 40);
    inst.castShadow = true;
    inst.userData.bay = ch.bay;
    drawerFrac[ch.bay] = ch.open;
    drawerTarget[ch.bay] = ch.open;
    initialOpen[ch.bay] = ch.open;
    layoutChain(inst, ch, ch.open);
    const holder = new THREE.Group();
    holder.add(inst);
    track(holder, { layer: 'chain', bay: ch.bay, row: ch.row, zone: 'chain', space: 'row' });
    chainInstances.push({ inst, ch });
  }
  // cables
  for (const c of DATA.cables) {
    const layer = ['power-jumper', 'power-feed', 'usb-pd'].includes(c.kind) ? 'power' : 'cables';
    track(makeCable(c), { layer, bay: c.bay || null, row: c.row ?? null, movable: !!c.movable, zone: c.kind, space: c.space });
  }
  for (const p of DATA.props ?? []) {
    if (p.kind === 'laptop') track(makeLaptop(p), { layer: 'cables', bay: p.bay ?? null, zone: 'laptop', space: p.space });
  }
  // bay labels
  for (const b of DATA.bays) {
    const el = document.createElement('div');
    el.className = 'label3d';
    el.textContent = b.id;
    const o = new CSS2DObject(el);
    o.position.set(...b.label_pos);
    track(o, { layer: 'labels', bay: b.id, row: b.row_index, movable: true, zone: 'label', space: 'row' });
  }
  buildUI();
  setView(params.get('view') || 'iso', false);
  applyTransforms();
  $('loading').classList.add('done');
  window.__ready = true;
}

// ------------------------------------------------------------------ transforms
let explode = 0;
const EXPLODE_ROW = 150;
function applyTransforms() {
  const R = DATA.rack;
  rowGroups.forEach((g, i) => { g.position.copy(g.userData.origin); g.position.z += explode * i * EXPLODE_ROW; });
  for (const o of tracked) {
    const u = o.userData;
    o.position.copy(u.base);
    o.visible = layerOn[u.layer];
    if (u.space === 'row') {
      if (u.movable && u.bay) o.position.y -= R.drawer_travel * (drawerFrac[u.bay] - (initialOpen[u.bay] ?? 0));
      if (u.movable) o.position.z += explode * 70;
      if (u.layer === 'cameras') o.position.z -= explode * 30;
    } else if (u.row != null) {
      o.position.z += explode * u.row * EXPLODE_ROW;          // ladders and braces follow their row
      if (u.layer === 'braces') o.position.y += explode * 60;
    } else if (u.layer === 'braces') {
      o.position.y += explode * 60;
    }
  }
  for (const { inst, ch } of chainInstances) layoutChain(inst, ch, drawerFrac[ch.bay]);
  updateSelectionBox();
}

// ------------------------------------------------------------------ UI
function buildUI() {
  const host = $('layers');
  for (const [key, label, on] of LAYERS) {
    const l = document.createElement('label');
    l.className = 'check';
    l.innerHTML = `<input type="checkbox" ${on ? 'checked' : ''}> ${label}`;
    l.querySelector('input').addEventListener('change', (e) => { layerOn[key] = e.target.checked; applyTransforms(); });
    host.appendChild(l);
  }
  $('drawers').addEventListener('input', (e) => {
    for (const k of Object.keys(drawerFrac)) { drawerFrac[k] = drawerTarget[k] = +e.target.value; }
    applyTransforms();
  });
  $('explode').addEventListener('input', (e) => { explode = +e.target.value; applyTransforms(); });
  $('xray').addEventListener('change', (e) => setXray(e.target.checked));
  $('autorotate').addEventListener('change', (e) => { controls.autoRotate = e.target.checked; });
  document.querySelectorAll('[data-view]').forEach((b) => b.addEventListener('click', () => setView(b.dataset.view)));
  $('infoClose').addEventListener('click', () => select(null));
  $('panelToggle').addEventListener('click', () => {
    const p = $('controls'); p.classList.toggle('collapsed');
    $('panelToggle').setAttribute('aria-expanded', String(!p.classList.contains('collapsed')));
  });
  if (window.matchMedia('(max-width: 720px)').matches) $('controls').classList.add('collapsed');
  if (params.has('xray')) { $('xray').checked = true; setXray(true); }
  if (params.has('open')) { for (const k of Object.keys(drawerFrac)) drawerFrac[k] = drawerTarget[k] = +params.get('open'); }
  if (params.has('explode')) { explode = +params.get('explode'); $('explode').value = explode; }
  if (params.has('bay')) {
    select(params.get('bay'), !params.has('hideui'));
    if (params.has('openbay')) drawerTarget[params.get('bay')] = +params.get('openbay') || 1;
  }
  if (params.has('hideui')) document.querySelectorAll('.topbar,.panel,.hint,.info').forEach((e) => (e.style.display = 'none'));
}

function setXray(on) {
  layerOn.ladders = !on;
  layerOn.braces = !on;
  for (const k of ['drawers', 'plates']) {
    const mat = k === 'drawers' ? MAT.drawers : MAT.plates;
    mat.transparent = on; mat.opacity = on ? 0.18 : 1; mat.depthWrite = !on; mat.needsUpdate = true;
  }
  applyTransforms();
}

// ------------------------------------------------------------------ camera views
function rackCenter() { const R = DATA.rack; return new THREE.Vector3(R.width / 2, R.depth / 2, R.height / 2); }
function toWorld(v) { return v.clone().applyMatrix4(root.matrixWorld); }
let camTween = null;
function setView(name, animate = true) {
  const R = DATA.rack;
  root.updateMatrixWorld(true);
  let target = rackCenter(), eye;
  if (name === 'front') eye = new THREE.Vector3(R.width / 2, -1900, R.height * 0.55);
  else if (name === 'rear') eye = new THREE.Vector3(R.width / 2 + 300, R.depth + 1700, R.height * 0.7);
  else if (name === 'side') eye = new THREE.Vector3(R.width + 1800, R.depth / 2 - 250, R.height * 0.6);
  else if (name === 'bay') {
    const bb = bayBounds(selectedBay || 'B2');
    target = bb.getCenter(new THREE.Vector3());
    eye = target.clone().add(new THREE.Vector3(0.42, -1, 0.62).normalize().multiplyScalar(720));
  } else eye = new THREE.Vector3(R.width * 1.5, -1300, R.height * 1.25);
  const to = { eye: toWorld(eye), target: toWorld(target) };
  if (!animate) { camera.position.copy(to.eye); controls.target.copy(to.target); controls.update(); return; }
  camTween = { from: { eye: camera.position.clone(), target: controls.target.clone() }, to, t0: performance.now(), dur: 900 };
}

// ------------------------------------------------------------------ selection
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
let downAt = null;
renderer.domElement.addEventListener('pointerdown', (e) => { downAt = [e.clientX, e.clientY]; });
renderer.domElement.addEventListener('pointerup', (e) => {
  if (!downAt || Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 5) return;
  pointer.set((e.clientX / window.innerWidth) * 2 - 1, -(e.clientY / window.innerHeight) * 2 + 1);
  raycaster.setFromCamera(pointer, camera);
  const hits = raycaster.intersectObjects(root.children, true).filter((h) => isShown(h.object) && h.object.userData.bay);
  select(hits.length ? hits[0].object.userData.bay : null);
});

function isShown(o) {
  for (let p = o; p; p = p.parent) if (!p.visible) return false;
  return true;
}

function bayBounds(id) {
  const box3 = new THREE.Box3();
  for (const o of tracked) if (o.userData.bay === id && ['trays', 'drawers', 'boards'].includes(o.userData.layer)) box3.expandByObject(o);
  // expandByObject works in world space; convert back into root space
  const inv = new THREE.Matrix4().copy(root.matrixWorld).invert();
  return box3.applyMatrix4(inv);
}
function updateSelectionBox() {
  if (!selectedBay) { selectionBox.visible = false; return; }
  root.updateMatrixWorld(true);
  selectionBox.box.copy(bayBounds(selectedBay)).expandByScalar(2);
  selectionBox.visible = true;
}

function select(id, showPanel = true) {
  selectedBay = id;
  updateSelectionBox();
  const info = $('info');
  if (!id) { info.hidden = true; return; }
  const b = DATA.bays.find((x) => x.id === id);
  const tags = [];
  if (b.camera) tags.push('<span class="tag ok">camera pod</span>');
  if (b.power_port) tags.push('<span class="tag ok">PWR port used</span>');
  if (b.classic) tags.push('<span class="tag ok">classic mode (laptop)</span>');
  if (b.board && !b.verified) tags.push('<span class="tag warn">board outline unverified</span>');
  $('infoBody').innerHTML = `
    <h3>Bay ${b.id}</h3>
    <p class="sub">Row ${b.row} · column ${b.col}</p>
    <div class="tags">${tags.join('')}</div>
    <dl>
      <dt>Board</dt><dd>${b.board ?? '<em>empty — universal plate</em>'}</dd>
      <dt>Debug USB</dt><dd>${b.usb ?? '—'}</dd>
      <dt>Cable</dt><dd>${b.cable ?? '—'}</dd>
      <dt>DATA socket</dt><dd>${b.data_port ? b.data_port.join(' + ') + ' position' : '—'}</dd>
      <dt>USB/IP</dt><dd>ESP32-S3 node · <code>usbip attach -r bay-${b.id.toLowerCase()}.local -b 1-1</code></dd>
    </dl>
    <div class="actions">
      <button id="actDrawer">${drawerTarget[id] > 0.5 ? 'Close' : 'Open'} drawer</button>
      <button id="actFocus">Focus</button>
    </div>`;
  info.hidden = !showPanel;
  $('actDrawer').onclick = () => { drawerTarget[id] = drawerTarget[id] > 0.5 ? 0 : 1; select(id); };
  $('actFocus').onclick = () => setView('bay');
}

// ------------------------------------------------------------------ ground + lights placement
function placeEnvironment() {
  const R = DATA.rack;
  const c = toWorld(rackCenter());
  sun.position.set(c.x + 900, c.y + 1800, c.z + 1100);
  sun.target.position.copy(c);
  const s = sun.shadow.camera;
  s.left = -900; s.right = 900; s.top = 900; s.bottom = -900; s.near = 100; s.far = 5000;
  s.updateProjectionMatrix();
  const ground = new THREE.Mesh(new THREE.CircleGeometry(2600, 64), std(0x161a20, 0, 0.92));
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);
}

// ------------------------------------------------------------------ loop
function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  labelRenderer.setSize(window.innerWidth, window.innerHeight);
}
window.addEventListener('resize', onResize);
controls.addEventListener('start', () => { $('hint').style.opacity = 0; });

function tick(now) {
  requestAnimationFrame(tick);
  if (camTween) {
    const k = Math.min(1, (now - camTween.t0) / camTween.dur);
    const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
    camera.position.lerpVectors(camTween.from.eye, camTween.to.eye, e);
    controls.target.lerpVectors(camTween.from.target, camTween.to.target, e);
    if (k >= 1) camTween = null;
  }
  if (DATA) {
    let moving = false;
    for (const k of Object.keys(drawerTarget)) {
      const d = drawerTarget[k] - drawerFrac[k];
      if (Math.abs(d) > 0.001) { drawerFrac[k] += Math.sign(d) * Math.min(Math.abs(d), 0.04); moving = true; }
    }
    if (moving) applyTransforms();
  }
  controls.update();
  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
}

load().then(() => { placeEnvironment(); requestAnimationFrame(tick); }).catch((err) => {
  console.error(err);
  $('loading').textContent = 'Could not load the model: ' + err.message;
});
